function memberNick(record){return state.members.find(m=>m.id===(record.memberId||record.id))?.username||record.memberUsername||record.username||(record.memberName==='Visitante'?'Visitante':'');}
'use strict';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state,view='stations',setup=false,search='',filterType='',filterDate='',polling=false,offset=0;
let stationSort=(()=>{try{const v=(localStorage.getItem('gz.stationSort')||localStorage.getItem('prime.stationSort'));return v==='az'||v==='za'?v:''}catch{return ''}})();
const money=c=>(c/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const cpfText=v=>{const d=String(v||'').replace(/\D/g,'');return d.length===11?d.replace(/(\d{3})(\d{3})(\d{3})(\d{2})/,'$1.$2.$3-$4'):(d||'Não informado')};
const loyaltyPointsText=n=>((n||0)/1000).toLocaleString('pt-BR',{maximumFractionDigits:3});
const duration=n=>{n=Math.max(0,Math.floor(n||0));return[String(Math.floor(n/3600)).padStart(2,'0'),String(Math.floor(n/60)%60).padStart(2,'0'),String(n%60).padStart(2,'0')].join(':')};
const datetime=t=>t?new Date(t).toLocaleString('pt-BR',{timeZone:state?.settings.timeZone||'America/Manaus',dateStyle:'short',timeStyle:'short'}):'—';
const activeStation=id=>state.sessions.find(s=>s.stationId===id&&s.status==='active');
const activeMember=id=>state.sessions.find(s=>s.memberId===id&&s.status==='active');
const remaining=s=>Math.max(0,Math.ceil((s.endsAt-(Date.now()+offset))/1000));
const isAdmin=()=>state?.operator.role==='admin';
// Versão atual do GameZoney Cliente, informada pelo servidor (sempre a versão do GameZoney, nunca uma antiga).
const gzClient=()=>'GameZoney Cliente '+(state?.clientVersion||'');
function toast(message){const el=$('#toast'),dialog=$('#modal');(dialog.open?dialog:document.body).appendChild(el);el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),5000)}
function recoveryBanner(){const a=state?.recoveryAudit;if(!a)return '';const cls=a.status==='warning'?'danger-zone':a.status==='ok'?'panel':'';return `<div class="panel ${cls}"><strong>${a.status==='checking'?'Verificação de saldo após reinício':a.status==='warning'?'Possível perda de saldo detectada':'Recuperação de saldo concluída'}</strong><p>${esc(a.message)}</p>${a.status==='warning'?'<button data-view-jump="logs">Abrir Sistema de log</button>':''}</div>`;}
function recoveryReviewHtml(data){if(!isAdmin()||!data)return '';const items=(data.items||[]).filter(r=>r.simultaneous===true||r.status==='pending'||r.status==='needs-refund'||r.status==='refunded').slice(0,30);if(!items.length&&!data.audit)return '';return `<div class="panel"><div class="toolbar"><div><h2>Verificação após queda simultânea</h2><p class="hint">Somente sessões que estavam ativas quando Servidor e PC ficaram indisponíveis ao mesmo tempo entram nesta verificação.</p></div></div>${data.audit?`<p><strong>${esc(data.audit.message)}</strong></p>`:''}${items.length?`<div class="table-wrap"><table><thead><tr><th>Cliente / máquina</th><th>Situação</th><th>Saldo analisado</th><th>Ação</th></tr></thead><tbody>${items.map(r=>{const pending=Math.max(0,Number(r.potentialLossSeconds)||0),status=r.status==='pending'?'Aguardando reconexão':r.status==='needs-refund'?'Possível perda de saldo':r.status==='refunded'?'Saldo devolvido pelo administrador':r.status==='review'?'Revisão recomendada':'Sem perda detectada';return `<tr><td>${esc(r.memberUsername||r.memberName||'Cliente')}<small class="subtext">${esc(r.stationName||'')}</small></td><td>${esc(status)}<small class="subtext">${esc(r.note||'')}</small></td><td>${r.refundedSeconds==null?'—':`Devolvido: ${duration(r.refundedSeconds)}`}${pending>0?`<small class="subtext">Diferença: ${duration(pending)}</small>`:''}</td><td>${r.status==='needs-refund'&&pending>0?`<button class="primary" data-action="recovery-refund" data-id="${esc(r.id)}">Devolver saldo (${duration(pending)})</button>`:'—'}</td></tr>`}).join('')}</tbody></table></div>`:'<p class="hint">Nenhuma sessão desta inicialização precisou de correção.</p>'}</div>`;}
$('#modal').addEventListener('close',()=>{if($('#modal').contains($('#toast')))document.body.appendChild($('#toast'));});
async function api(url,body){const r=await fetch('/api'+url,{method:body===undefined?'GET':'POST',headers:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});let result;try{result=await r.json()}catch{throw Error('Não foi possível ler a resposta do servidor.')}if(!r.ok){if(r.status===401&&!url.includes('login'))await auth();throw Error(result.error||'Operação não concluída.')}return result}
async function auth(){const a=await api('/auth');setup=a.setup;$('#shell').classList.toggle('hidden',!a.operator);$('#auth').classList.toggle('hidden',!!a.operator);$('#auth-title').textContent=setup?'Prepare sua arena.':'Bem-vindo de volta.';$('#auth-description').textContent=setup?'Crie o administrador do servidor. Use uma senha de 4 a 24 caracteres.':'Entre para iniciar o atendimento.';$('#auth-form button').textContent=setup?'Criar administrador →':'Entrar no servidor →';if(a.operator)await refresh(true);else state=null}
$('#auth-form').onsubmit=async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;$('#auth-error').textContent='';const data=Object.fromEntries(new FormData(e.target));try{if(setup)await api('/setup',data);await api('/login',data);e.target.reset();await auth()}catch(err){$('#auth-error').textContent=err.message}finally{button.disabled=false}};
$('#logout').onclick=async()=>{await api('/logout',{});state=null;$('#modal').close();await auth()};
document.querySelectorAll('nav button').forEach(button=>button.onclick=()=>{if(!isAdmin()&&['settings','balance'].includes(button.dataset.view))return;view=button.dataset.view;search='';filterDate='';filterType='';if(typeof gzNavFix==='function')gzNavFix();document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b===button));$('#view-title').textContent=(button.querySelector('span')?.textContent||button.textContent).trim();render()});
function modal(title,body){$('#modal-title').textContent=title;$('#modal-body').innerHTML=body;$('#modal-error').textContent='';$('#modal').showModal()}
// 1.0.5: o navegador/WebView2 nunca oferece "Salvar senha": senhas usam campo de texto mascarado (data-secret), não type=password.
// Reserva: qualquer type=password criado depois é convertido na hora; copiar/recortar de um campo de senha é bloqueado.
function maskSecrets(root){for(const i of (root.querySelectorAll?root:document).querySelectorAll('input[type=password]')){i.type='text';i.setAttribute('data-secret','');i.setAttribute('autocomplete','off');i.setAttribute('autocapitalize','off');i.spellcheck=false;i.setAttribute('data-lpignore','true');i.setAttribute('data-form-type','other')}}
new MutationObserver(list=>{for(const m of list)for(const n of m.addedNodes)if(n.nodeType===1)maskSecrets(n.parentNode||n)}).observe(document.documentElement,{childList:true,subtree:true});
for(const ev of ['copy','cut'])document.addEventListener(ev,e=>{if(e.target?.matches?.('input[data-secret]'))e.preventDefault()},true);
// 1.0.5: caixa de confirmação do próprio painel, no lugar do confirm() do navegador (que mostrava "127.0.0.1:3000 diz").
// A pergunta vai em destaque; o que vem depois do primeiro "? " vira a explicação embaixo. Esc ou Cancelar = não.
function ask(text,{ok='Confirmar',cancel='Cancelar'}={}){return new Promise(resolve=>{const d=$('#ask'),t=String(text),i=t.indexOf('? ');$('#ask-question').textContent=i>0?t.slice(0,i+1):t;$('#ask-detail').textContent=i>0?t.slice(i+2):'';$('#ask-yes').textContent=ok;$('#ask-no').textContent=cancel;let done=false;const finish=v=>{if(done)return;done=true;if(d.open)d.close();resolve(v)};$('#ask-yes').onclick=()=>finish(true);$('#ask-no').onclick=()=>finish(false);d.oncancel=e=>{e.preventDefault();finish(false)};d.showModal();$('#ask-yes').focus()})}
$('#close-modal').onclick=()=>$('#modal').close();
// 3.0.46: caixa de confirmação Sim/Não no padrão do painel (fica por cima de outras janelas).
function askYesNo(title,message){return new Promise(resolve=>{let box=document.getElementById('confirm-box');if(!box){box=document.createElement('dialog');box.id='confirm-box';box.className='confirm-box';box.innerHTML='<div class="dialog-head"><h2 id="confirm-title"></h2></div><p id="confirm-message"></p><div class="confirm-actions"><button type="button" class="primary" data-answer="yes">Sim</button><button type="button" data-answer="no">Não</button></div>';document.body.appendChild(box);}box.querySelector('#confirm-title').textContent=title;box.querySelector('#confirm-message').textContent=message;let done=false;const finish=v=>{if(done)return;done=true;box.oncancel=null;box.querySelectorAll('[data-answer]').forEach(b=>b.onclick=null);if(box.open)box.close();resolve(v)};box.querySelector('[data-answer="yes"]').onclick=()=>finish(true);box.querySelector('[data-answer="no"]').onclick=()=>finish(false);box.oncancel=e=>{e.preventDefault();finish(false)};box.showModal();box.querySelector('[data-answer="no"]').focus();})}
function formAction(fn){$('#modal-body form').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;$('#modal-error').textContent='';try{await fn(Object.fromEntries(new FormData(e.target)));$('#modal').close();await refresh(true);toast('Operação registrada.')}catch(error){$('#modal-error').textContent=error.message}finally{e.submitter.disabled=false}}}
async function refresh(force=false){if(polling)return;polling=true;try{const previous=state?JSON.stringify({...state,serverNow:0}):'';state=await api('/state');const changed=previous!==JSON.stringify({...state,serverNow:0});offset=state.serverNow-Date.now();document.querySelectorAll('nav [data-admin]').forEach(b=>b.classList.toggle('hidden',!isAdmin()));if(!isAdmin()&&['settings','balance'].includes(view)){view='stations';$('#view-title').textContent='Painel de controle';document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===(typeof gzNavView==='function'?gzNavView():view)));}$('#operator-name').innerHTML=`<b>${esc(state.operator.username)}</b>${state.isOwner?'Administrador principal':isAdmin()?'Administrador':'Operador'}`;{const c=state.cashSummary;$('#cash-status').textContent=c?` • Caixa nº ${String(c.number).padStart(4,'0')} aberto`:' • Caixa fechado';$('#cash-status').className=c?'cash-on':'cash-off';}$('#connection').textContent='● Conectado ao servidor';$('#connection').style.color='';if((force||changed||!$('#view').innerHTML)&&(force||view!=='balance'&&view!=='events'&&view!=='ranking'&&view!=='history'&&view!=='settings'&&view!=='logs'&&view!=='stats'&&view!=='cash'&&view!=='machines'&&view!=='finance'&&view!=='loyalty'&&view!=='shop'||!$('#view').innerHTML)&&document.activeElement?.id!=='search')render()}catch(e){$('#connection').textContent='● Servidor desconectado';$('#connection').style.color='#ff7b87'}finally{polling=false}}
function stationCard(station){const session=activeStation(station.id),adminPC=state.pcAdminStations?.includes(station.id);return `<article class="station ${session?'occupied':''}"><div class="station-top"><div><h3>${station.kind==='computer'?`<span class="connection-dot ${state.status[station.id]?.connected?'online':'offline'}" role="img" aria-label="${state.status[station.id]?.connected?'Cliente conectado':'Cliente desconectado'}" title="${state.status[station.id]?.connected?'Cliente conectado':'Cliente desconectado'}"></span> `:''}${esc(station.name)}</h3><small>${station.kind==='tv'?'TV / HDMI '+station.hdmi:'COMPUTADOR / CLIENTE GameZoney'} · ${esc(station.ip||'Sem IP')}</small></div><span class="badge ${session?'on':''}">${adminPC?'ADMINISTRAÇÃO':session?'EM USO':station.active?'LIVRE':'INATIVA'}</span></div><div class="station-body"><span class="muted">${adminPC?'MODO ADMINISTRADOR':session?'TEMPO RESTANTE':'PRONTA PARA JOGAR'}</span><div class="timer" ${session?`data-end="${session.endsAt}"`:''}>${session?duration(remaining(session)):'— : — : —'}</div><div class="member">${esc(adminPC?'Acesso administrativo':session?.memberName||'Nenhum cliente conectado')}</div><div class="detail"><span>Início</span><span>${datetime(session?.startedAt)}</span></div><div class="detail"><span>Término previsto</span><span>${datetime(session?.endsAt)}</span></div><div class="actions">${session?`<button data-action="credit" data-id="${session.memberId}">+ Adicionar tempo</button><button class="danger" data-action="finish" data-id="${station.id}">Encerrar</button>`:`<button class="primary" data-action="start" data-id="${station.id}" ${!station.active||adminPC?'disabled':''}>Iniciar sessão →</button><button data-action="guest-start" data-id="${station.id}" ${!station.active||adminPC?'disabled':''} title="Liberar sem cadastro: informe só o tempo e a forma de pagamento">Visitante</button>`}</div></div><div class="device-actions">${isAdmin()?`<button class="link" data-action="station-edit" data-id="${station.id}">Configurar</button>`:''}${station.kind==='computer'&&isAdmin()?`<button class="link" data-action="pc-enroll" data-id="${station.id}">Associação por arquivo (alternativa)</button><button class="link" data-action="pc-layout" data-id="${station.id}">Layout do login</button>`:''}${station.kind==='computer'&&isAdmin()&&!session&&!adminPC&&(!station.active||!state.status[station.id]?.connected)?`<button class="link danger" data-action="pc-remove" data-id="${station.id}">Remover computador</button>`:''}${station.kind==='tv'&&isAdmin()&&!session?`<button class="link danger" data-action="tv-remove" data-id="${station.id}">Remover console</button>`:''}${station.kind==='tv'?`${isAdmin()?`<button class="link" data-action="pair" data-id="${station.id}">Parear TV</button>${station.tvType!=='android'?`<button class="link" data-action="pin" data-id="${station.id}">Informar PIN</button><button class="link" data-action="import" data-id="${station.id}">Importar pareamento</button>`:''}`:''}<button class="link" data-action="hdmi" data-id="${station.id}">Testar HDMI</button>`:''}</div><div class="device-message">${esc(state.status[station.id]?.message|| (station.kind==='tv'?'Controle VIDAA disponível.':'Associe o cliente instalado no computador.'))}</div></article>`}
// 3.0.67: olho para exibir/ocultar o valor do Caixa de hoje (a escolha fica guardada neste navegador)
let cashHidden=(()=>{try{return (localStorage.getItem('gz-caixa-oculto')??localStorage.getItem('pa-caixa-oculto'))==='1'}catch{return false}})();
const eyeIcon=hidden=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M2 12s3.6-7 10-7 10 7 10 7-3.6 7-10 7S2 12 2 12z"/><circle cx="12" cy="12" r="3"/>${hidden?'<path d="M4 4l16 16"/>':''}</svg>`;
function render(){if(!state)return;const node=$('#view');if(view==='stations'){const active=state.sessions.filter(s=>s.status==='active'),available=state.stations.filter(s=>s.active&&!activeStation(s.id)&&!state.pcAdminStations?.includes(s.id));node.innerHTML=`${recoveryBanner()}<div class="stats">${(()=>{const total=Math.max(1,state.stations.length),c=state.cashSummary,bar=v=>`<div class="stat-bar"><span style="width:${Math.round(Math.min(1,v)*100)}%"></span></div>`;return `<div class="stat"><small>Estações em uso</small><strong>${active.length}<span class="accent"> / ${state.stations.length}</span></strong><em>Acompanhamento em tempo real</em>${bar(active.length/total)}</div><div class="stat"><small>Disponíveis</small><strong>${available.length}</strong><em>Prontas para iniciar</em>${bar(available.length/total)}</div><div class="stat stat-cash"><button type="button" class="stat-eye" data-action="toggle-cash" aria-pressed="${cashHidden}" aria-label="${cashHidden?'Exibir valor':'Ocultar valor'}" title="${cashHidden?'Exibir valor':'Ocultar valor'}">${eyeIcon(cashHidden)}</button><small>Caixa de hoje</small><strong class="cash-value">${c?(cashHidden?'R$ ••••••':money(c.totalCents)):'—'}</strong><em>${c?`${c.recharges} recarga(s) • ${c.shopCount} venda(s) PDV`:'Caixa fechado'}</em>${bar(c?1:0)}</div><div class="stat stat-hour">${isAdmin()?`<button type="button" class="stat-eye stat-gear" data-action="hour-config" aria-label="Configurar valor da hora" title="Configurar valor da hora">${gearIcon}</button>`:''}<small>Valor da hora</small><strong>${money(state.settings.hourCents)}</strong><em>${state.promotions.filter(p=>p.active).length} promoção(ões) ativa(s)</em>${bar(0)}</div>`})()}</div><div class="toolbar"><h2>Sua arena, ao vivo <span class="muted">/ ${state.stations.length} estações</span></h2><div class="toolbar-actions"><div class="sort-group" role="group" aria-label="Organizar estações"><span>Organizar</span><button data-station-sort="az" class="${stationSort==='az'?'active':''}" title="Ordenar de A a Z">A-Z</button><button data-station-sort="za" class="${stationSort==='za'?'active':''}" title="Ordenar de Z a A">Z-A</button></div><button data-action="guest-batch"><svg class="btn-icon" viewBox="0 0 24 24"><circle cx="8" cy="9" r="3"/><circle cx="16" cy="9" r="3"/><path d="M2 20c1-3 3-5 6-5s5 2 6 5M14 16c3 0 6 1 8 4"/></svg>Visitantes em grupo</button>${isAdmin()?'<button data-business="pc-actions"><svg class="btn-icon" viewBox="0 0 24 24"><path d="M13 2L4 14h7l-1 8 9-12h-7z"/></svg>Ações dos PCs</button><button class="primary" data-action="station-edit"><svg class="btn-icon" viewBox="0 0 24 24"><path d="M12 5v14M5 12h14"/></svg>Nova estação</button>':''}</div></div>${pendingPCs()}<div class="monitor-grid">${sortedStations().map(stationTile).join('')}</div>`}
 if(view==='members'){const term=search.toLowerCase().replace(/\D/g,''),list=state.members.filter(m=>!m.guest).filter(m=>(m.name+' '+(m.username||'')+' '+(m.phone||'')+' '+(m.cpf||'')).toLowerCase().includes(search.toLowerCase())||(term&&String(m.cpf||'').includes(term)));node.innerHTML=`<div class="toolbar"><div><h2>Clientes da arena</h2><p class="hint">Clique no nome para adicionar minutos ou escolher uma promoção.</p></div><div class="toolbar-actions">${state.isOwner?'<button data-action="member-import">Importar planilha</button>':''}<button class="primary" data-action="member-edit">+ Novo cliente</button></div></div><div class="toolbar"><input class="search" id="search" placeholder="Buscar nome, nick, CPF ou telefone" value="${esc(search)}"><span class="muted">${list.length} clientes</span></div><div class="table-wrap"><table><thead><tr><th>Cliente</th><th>Saldo disponível</th><th>Sessão atual</th><th>Status</th><th></th></tr></thead><tbody>${list.map(m=>{const s=activeMember(m.id);return `<tr><td><button class="link name-cell" data-action="credit" data-id="${m.id}"><span class="avatar">${esc(m.name.slice(0,2).toUpperCase())}</span><span>${esc(m.name)}<small class="subtext">${esc(m.username?'@'+m.username:'Nick ainda não definido')} · CPF ${esc(cpfText(m.cpf))} · ${esc(m.phone||'Sem telefone')}</small></span></button></td><td>${duration(m.creditSeconds)}<small class="subtext">${m.loyaltyEnabled===false?'Fidelidade DESATIVADA · medalhas: '+loyaltyPointsText(m.pointsMilli):'Medalhas de fidelidade: '+loyaltyPointsText(m.pointsMilli)}</small></td><td>${s?`${esc(s.stationName)} · <span data-end="${s.endsAt}">${duration(remaining(s))}</span>`:'—'}</td><td><span class="badge ${m.active?'on':''}">${m.active?'ATIVO':'INATIVO'}</span></td><td><button data-action="member-edit" data-id="${m.id}">Editar</button></td></tr>`}).join('')||'<tr><td colspan="5">Nenhum cliente encontrado. Cadastre o primeiro para começar.</td></tr>'}</tbody></table></div>`;$('#search').oninput=e=>{search=e.target.value;const pos=e.target.selectionStart;render();$('#search').focus();$('#search').setSelectionRange(pos,pos)}}
 if(view==='history')renderHistory().catch(e=>toast(e.message));
 if(view==='finance')renderFinance().catch(e=>toast(e.message));if(view==='events'&&typeof renderEvents==='function')renderEvents().catch(e=>toast(e.message));if(view==='ranking'&&typeof renderRanking==='function')renderRanking().catch(e=>toast(e.message));if(view==='loyalty')renderLoyalty().catch(e=>toast(e.message));
 if(view==='logs')renderLogs().catch(e=>toast(e.message));
 if(view==='balance')renderBalance().catch(e=>toast(e.message));if(view==='settings')renderSettings();if(view==='shop')renderShop().catch(e=>toast(e.message));if(view==='machines')renderMachineSettings();if(view==='stats')renderStats().catch(e=>toast(e.message));if(view==='cash')renderCash().catch(e=>toast(e.message));
}
async function renderLogs(){const params=new URLSearchParams();if(search)params.set('nick',search);if(filterType)params.set('type',filterType);if(filterDate)params.set('from',new Date(filterDate+'T00:00:00').toISOString());const [logs,recovery]=await Promise.all([api('/logs?'+params),isAdmin()?api('/recovery-review'):Promise.resolve(null)]);if(view!=='logs')return;$('#view').innerHTML=`${sessionTabs('logs')}${recoveryReviewHtml(recovery)}<div class="toolbar"><h2>Registro de atividades</h2><a class="button" href="/api/logs.csv?${params}"><button>Exportar CSV ↓</button></a></div><div class="filters"><input id="log-search" placeholder="Buscar Usuário/Nick" value="${esc(search)}"><input type="date" id="log-date" value="${esc(filterDate)}"><select id="log-type"><option value="">Todos os tipos</option>${['inicio','fim','recarga','membro','tv','erro','login','config','backup','servidor','recuperacao-energia','recuperacao-saldo'].map(t=>`<option value="${t}" ${filterType===t?'selected':''}>${t==='membro'?'cliente':t}</option>`).join('')}</select><button id="filter-logs">Filtrar</button></div><div class="table-wrap"><table><thead><tr><th>Data e hora</th><th>Operador</th><th>Tipo</th><th>Usuário/Nick</th><th>Descrição</th></tr></thead><tbody>${logs.map(l=>`<tr><td>${datetime(l.at)}</td><td>${esc(l.actor)}</td><td><span class="badge ${l.type==='erro'?'red':''}">${esc(l.type==='membro'?'cliente':l.type)}</span></td><td>${esc(l.memberId?memberNick(l):'—')}</td><td style="white-space:normal">${esc(l.detail)}</td></tr>`).join('')}</tbody></table></div><p class="hint">Exibindo até 1.000 registros por consulta. A busca por nick considera atividades vinculadas ao cliente a partir desta atualização.</p>`;$('#filter-logs').onclick=()=>{search=$('#log-search').value;filterDate=$('#log-date').value;filterType=$('#log-type').value;renderLogs().catch(e=>toast(e.message))}}
// Restaurado (3.0.17): estas funcoes foram perdidas em uma atualizacao anterior; sem elas os botoes
// "+ Adicionar tempo", Iniciar, Encerrar, Editar cliente/estacao, Promocoes e Configuracoes nao abriam.
/* 1.0.5: valor da hora e fuso pela engrenagem do card "Valor da hora" (Painel de controle; valor exige senha do administrador). Configuração › Servidor IP (abaixo do Backup): botão Servidor IP (cabo, Wi-Fi ou nuvem) e Atualizar Automático (IP atual + portas + firewall). */
const GZ_NET_KIND={cabo:'Cabo de rede (Ethernet)',wifi:'Wi-Fi',virtual:'Adaptador virtual/VPN'};
