async function hourConfig(){if(!isAdmin())return toast('Somente o administrador pode alterar o valor da hora.');const st=state.settings;
modal('Valor da hora',`<form><label>Valor de 1 hora (R$)<input name="price" type="number" min="0" step="0.01" required value="${(st.hourCents/100).toFixed(2)}"></label><p class="hint">Minutos avulsos são proporcionais ao valor da hora, arredondados em centavos. Alterações não modificam recargas já registradas. Para mudar o valor, será pedida a senha do administrador.</p><div class="dialog-actions"><button class="primary">Confirmar</button></div></form>`);
formAction(async d=>{const raw=String(d.price).replace(',','.').trim(),v=Number(raw);if(raw===''||!Number.isFinite(v)||v<0)throw Error('Informe um valor válido para 1 hora.');const cents=Math.round(v*100);if(cents===state.settings.hourCents)return;
 modal('Senha do administrador',`<form><p class="hint">Novo valor de 1 hora: <strong>${money(cents)}</strong> (atual: ${money(state.settings.hourCents)}). Confirme com a sua senha de administrador.</p><label>Senha do administrador<input name="authPassword" type="text" data-secret autocomplete="off" autocapitalize="off" spellcheck="false" data-lpignore="true" data-1p-ignore data-form-type="other" maxlength="128" required></label><div class="dialog-actions"><button class="primary">Confirmar</button></div></form>`);$('#modal-body input').focus();formAction(async p=>{if(!p.authPassword)throw Error('Informe a senha do administrador.');await api('/settings',{hourCents:cents,authPassword:p.authPassword})});throw Object.assign(Error(''),{keepOpen:true})})}
/* 1.0.5: na tela mostra só o IP (ou domínio), sem http:// e sem a porta. */
function gzHost(url){try{return new URL(url).hostname}catch{return String(url||'')}}
function renderSettings(){if(!isAdmin()){$('#view').innerHTML='<div class="empty">Esta área é reservada ao administrador.</div>';return}
$('#view').innerHTML='<div id="cfg-accounts"></div><div id="cfg-machines"></div>';renderAccounts().catch(e=>toast(e.message));renderMachineSettings($('#cfg-machines'));
const net=document.createElement('section');net.id='net-section';net.className='panel';net.innerHTML=`<h2>Servidor IP</h2><p class="hint">Endereço usado pelas TVs e pelos PCs para chegar a este servidor: <strong id="net-current">${esc(gzHost(state.settings.serverUrl))}</strong><span id="net-hint" class="subtext"></span></p><p class="hint">Se o IP desta máquina mudou (troca de roteador, cabo ↔ Wi-Fi), use <strong>Atualizar Automático</strong>: o servidor confere o IP em uso, ajusta o endereço, verifica as portas e o firewall e mostra se está disponível localmente ou em nuvem. Os PCs reencontram o servidor sozinhos pela rede.</p><div class="dialog-actions" style="justify-content:flex-start"><button type="button" id="net-config" style="flex:0 0 auto">Servidor IP</button><button type="button" class="primary" id="net-auto" style="flex:0 0 auto">Atualizar Automático ›</button></div>`;
const place=()=>{if(view==='settings'&&!net.isConnected)$('#view').append(net)};const b=typeof renderBackupSettings==='function'?renderBackupSettings():null;Promise.resolve(b).catch(()=>{}).finally(place);
const paintHint=async()=>{try{const n=await api('/network');let host='';try{host=new URL(state.settings.serverUrl).hostname}catch{}const mine=n.interfaces.find(i=>i.address===host);const h=net.querySelector('#net-hint');h.textContent=mine?`IP do ${GZ_NET_KIND[mine.kind]} desta máquina (${mine.name}).`:/^\d+\.\d+\.\d+\.\d+$/.test(host)?`Atenção: ${host} não é um IP desta máquina. Use Atualizar Automático.`:'Endereço externo (servidor em nuvem/domínio).';h.style.color=mine||!/^\d+\.\d+\.\d+\.\d+$/.test(host)?'':'#ff8793'}catch{}};paintHint();
net.querySelector('#net-auto').onclick=async e=>{const btn=e.target;btn.disabled=true;const old=btn.textContent;btn.textContent='Verificando…';try{const r=await api('/network/auto',{});await refresh(true);if(view!=='settings')return;net.querySelector('#net-current').textContent=gzHost(state.settings.serverUrl);paintHint();const where=r.mode==='cloud'?'em nuvem':'localmente (rede local)';modal('Atualizar Automático',`<div class="promotion" style="${r.available?'border-color:#3d5b48;background:#1d2a23':'border-color:#61303a;background:#392027'}"><div><strong>${r.available?'✔ Servidor disponível '+where:'✖ Servidor ainda não está 100% disponível '+where}</strong><small>${r.mode==='cloud'?'TVs e PCs acessam pelo endereço em nuvem':'TVs e PCs da mesma rede acessam este servidor'}: ${esc(gzHost(r.serverUrl))}${r.changed?' (atualizado)':''}</small></div></div>${r.checks.map(c=>`<div class="promotion" style="${c.ok?'':'border-color:#61303a;background:#392027'}"><div><strong>${c.ok?'✔':'✖'} ${esc(c.name)}</strong><small>${esc(c.detail)}</small></div></div>`).join('')}<p class="hint">${r.checks.every(c=>c.ok)?'Tudo pronto: o servidor está funcionando com este IP.':'Corrija os itens marcados com ✖ e clique em Atualizar Automático novamente.'}</p>`)}catch(err){toast(err.message)}finally{btn.disabled=false;btn.textContent=old}};
net.querySelector('#net-config').onclick=async()=>{let n;try{n=await api('/network')}catch(e){return toast(e.message)}let cur={};try{cur=new URL(state.settings.serverUrl)}catch{}const opts=n.interfaces.map((i,k)=>`<label style="display:flex;gap:10px;align-items:center;margin:0 0 10px;padding:12px;border:1px solid var(--line);border-radius:8px;cursor:pointer"><input type="radio" name="choice" value="ip:${esc(i.address)}" style="width:auto;margin:0" ${cur.hostname===i.address||(!cur.hostname&&k===0)?'checked':''}><span><strong>${esc(GZ_NET_KIND[i.kind])}</strong> — ${esc(i.address)}<small class="subtext">${esc(i.name)}</small></span></label>`).join('')||'<p class="hint">Nenhuma rede ativa encontrada nesta máquina. Confira o cabo ou o Wi-Fi.</p>';const isCloud=!!cur.hostname&&!n.interfaces.some(i=>i.address===cur.hostname);
modal('Servidor IP',`<form><p class="hint">Escolha por qual rede as TVs e os PCs acessam este servidor. Se a máquina usa cabo e Wi-Fi ao mesmo tempo, escolha a rede em que estão as TVs e os PCs (normalmente o cabo).</p>${opts}<label style="display:flex;gap:10px;align-items:center;margin:0 0 10px;padding:12px;border:1px solid var(--line);border-radius:8px;cursor:pointer"><input type="radio" name="choice" value="cloud" style="width:auto;margin:0" ${isCloud?'checked':''}><span><strong>Servidor em nuvem / outro endereço</strong><small class="subtext">Domínio ou IP externo, ex.: https://gamezoney.exemplo.com.br</small></span></label><label id="cloud-box" class="${isCloud?'':'hidden'}">Endereço completo<input name="cloudUrl" value="${isCloud?esc(cur.origin):''}" placeholder="https://gamezoney.exemplo.com.br"></label><input type="hidden" name="port" value="${esc(isCloud?n.port:(cur.port||n.port))}"><div class="dialog-actions"><button class="primary">Usar este endereço</button></div></form>`);
const f=$('#modal-body form');f.onchange=()=>{const c=f.querySelector('input[name=choice]:checked')?.value==='cloud';$('#cloud-box').classList.toggle('hidden',!c)};
formAction(async d=>{if(!d.choice)throw Error('Escolha uma opção.');let url;if(d.choice==='cloud'){url=String(d.cloudUrl||'').trim();if(!url)throw Error('Informe o endereço do servidor em nuvem.');if(!/^https?:\/\//i.test(url))url='https://'+url}else{const port=Number(d.port);if(!Number.isInteger(port)||port<1||port>65535)throw Error('Porta inválida.');url=`http://${d.choice.slice(3)}:${port}`}await api('/settings',{serverUrl:url})})}}
function editMember(id){const m=state.members.find(m=>m.id===id)||{};modal(id?'Editar cliente':'Novo cliente',`<form><label>Nome completo<input name="name" required maxlength="120" value="${esc(m.name)}"></label><label>Usuário/Nick<input name="username" autocomplete="off" minlength="3" maxlength="32" pattern="[A-Za-z0-9._ \-]{3,32}" title="3 a 32 caracteres: letras sem acento, números, espaço, ponto, hífen ou sublinhado" ${!id||m.username?'required':''} value="${esc(m.username)}" placeholder="Ex.: Joao 123"></label><label>Senha (4 a 20 caracteres)<input name="password" type="text" data-secret autocomplete="off" autocapitalize="off" spellcheck="false" data-lpignore="true" data-1p-ignore data-form-type="other" minlength="4" maxlength="20" placeholder="${m.hasPassword?'Deixe em branco para manter a senha':'Opcional: o cliente criará no primeiro acesso'}"></label><p class="hint">${id&&!m.hasPassword?'Senha pendente: o cliente deverá cadastrar a senha ao entrar no PC. ':''}Senhas curtas são aceitas. A senha ficará salva de forma protegida para o cliente de computadores. Nas TVs, a recepção inicia a sessão sem pedir essa senha.</p><label>CPF (opcional)<input name="cpf" inputmode="numeric" autocomplete="off" maxlength="14" placeholder="000.000.000-00" value="${esc(m.cpf&&String(m.cpf).replace(/\D/g,'').length===11?cpfText(m.cpf):(m.cpf||''))}"></label><label>Telefone<input name="phone" maxlength="40" value="${esc(m.phone)}"></label><label>Observações<textarea name="notes" maxlength="500">${esc(m.notes)}</textarea></label><label><input type="checkbox" name="active" ${m.active!==false?'checked':''}>Cliente ativo</label><label><input type="checkbox" name="loyaltyEnabled" ${m.loyaltyEnabled!==false?'checked':''}>Ativar programa fidelidade</label><p class="hint">Desmarcado: o cliente não ganha medalhas nas recargas com promoção nem o prêmio automático. As medalhas que ele já tem continuam no saldo.</p><button class="primary">Salvar cadastro</button></form>`);formAction(d=>api('/members',{...d,id,active:d.active==='on',loyaltyEnabled:d.loyaltyEnabled==='on'}))}
/* 1.0.5: pagamento combinado (até 3 formas, ex.: Pix + Cartão + Dinheiro) — recarga, visitante e PDV. */
const PAY_RECHARGE={cash:'Dinheiro',pix:'Pix',credit:'Cartão (Crédito)',debit:'Cartão (Débito)'},PAY_SHOP={cash:'Dinheiro',pix:'Pix',card:'Cartão'};
function payMixHtml(methods){const opts='<option value="">Forma</option>'+Object.entries(methods).map(([k,v])=>`<option value="${k}">${v}</option>`).join('');return `<div class="pay-mix"><label class="pay-mix-toggle"><input type="checkbox" class="pm-on"> Pagamento combinado (até 3 formas)</label><div class="pm-rows hidden">${[0,1,2].map(i=>`<div class="pm-row"><select class="pm-method" aria-label="Forma ${i+1}">${opts}</select><input class="pm-cents" type="number" min="0.01" step="0.01" placeholder="Valor (R$)" aria-label="Valor ${i+1}"></div>`).join('')}<p class="hint pm-rest"></p></div></div>`}
function payMix(root,total,onToggle){const on=root.querySelector('.pm-on'),rows=root.querySelector('.pm-rows'),rest=root.querySelector('.pm-rest');
 const read=()=>[...root.querySelectorAll('.pm-row')].map(r=>({method:r.querySelector('.pm-method').value,cents:Math.round((Number(String(r.querySelector('.pm-cents').value).replace(',','.'))||0)*100)})).filter(p=>p.method);
 const paint=()=>{if(!on.checked)return;const t=total(),sum=read().reduce((a,p)=>a+p.cents,0),d=t-sum;rest.textContent=`Total ${money(t)} • informado ${money(sum)} • ${d===0?'confere ✔':d>0?'falta '+money(d):'passou '+money(-d)}`;rest.style.color=d===0?'var(--green)':'#ff8793'};
 on.onchange=()=>{rows.classList.toggle('hidden',!on.checked);if(onToggle)onToggle(on.checked);paint()};root.addEventListener('input',e=>{if(e.target!==on)paint()});root.addEventListener('change',e=>{if(e.target!==on)paint()});
 return{active:()=>on.checked,paint,payments(){if(!on.checked)return null;const list=read();if(list.length<2)throw Error('Pagamento combinado: escolha pelo menos 2 formas.');if(new Set(list.map(p=>p.method)).size!==list.length)throw Error('Não repita a mesma forma de pagamento no combinado.');if(list.some(p=>p.cents<1))throw Error('Informe o valor de cada forma de pagamento.');const sum=list.reduce((a,p)=>a+p.cents,0),t=total();if(sum!==t)throw Error(`A soma do combinado (${money(sum)}) precisa ser igual ao total (${money(t)}).`);return list}}}
function payMixLabel(list,names){return 'Combinado: '+list.map(p=>(names[p.method]||p.method)+' '+money(p.cents)).join(' + ')}
function credit(id){const m=state.members.find(m=>m.id===id),s=activeMember(id);modal('Adicionar tempo • '+m.name,`<div class="balance"><span>Tempo disponível</span><strong ${s?`data-end="${s.endsAt}"`:''}>${duration(s?remaining(s):m.creditSeconds)}</strong></div><div class="balance"><span>Medalhas de fidelidade</span><strong>${loyaltyPointsText(m.pointsMilli)}</strong></div><form><span class="eyebrow">ESCOLHA UMA PROMOÇÃO</span><p class="hint" style="margin:4px 0 10px">Medalhas de fidelidade só são gerados ao escolher uma promoção.</p><div class="promo-options">${state.promotions.filter(p=>p.active).map(p=>`<button type="button" data-promo="${p.id}"><strong>${esc(p.name)}</strong><small>${p.minutes} min · ${money(p.cents)}</small></button>`).join('')||'<p class="hint">Nenhuma promoção ativa.</p>'}</div><div class="credit-mode" role="radiogroup" aria-label="Informar recarga"><span>Informar recarga</span><label><input type="radio" name="creditMode" value="minutes" checked> Em minutos</label><label><input type="radio" name="creditMode" value="value"> Em valor</label></div><label id="credit-input-label"><span id="credit-input-title">Quantidade de minutos</span><input id="credit-minutes" type="number" min="1" max="43200" step="1" value="60" required></label><div class="balance locked"><span id="quote-title">Valor da recarga</span><strong class="price" id="quote">${money(state.settings.hourCents)}</strong></div><label id="credit-payment">Forma de pagamento<select name="paymentMethod" required><option value="">Selecione</option><option value="cash">Dinheiro</option><option value="pix">Pix</option><option value="credit">Cartão (Crédito)</option><option value="debit">Cartão (Débito)</option></select></label><div id="credit-paymix">${payMixHtml(PAY_RECHARGE)}</div><div id="credit-free" class="hidden"><p class="hint" style="margin:0 0 6px"><strong>Pacote grátis:</strong> informe a OBS e confirme com a sua senha do servidor.</p><label>OBS (obrigatório)<textarea name="obs" maxlength="300" placeholder="Ex.: cortesia aniversário, compensação de queda de energia..."></textarea></label><label>Chave de autenticação (senha do usuário logado no servidor)<input name="authPassword" type="text" data-secret autocomplete="off" autocapitalize="off" spellcheck="false" data-lpignore="true" data-1p-ignore data-form-type="other" maxlength="128"></label></div><p class="hint">${s?'O tempo será acrescentado à sessão em andamento.':'Escolha uma estação para iniciar agora, ou guarde os minutos no saldo.'} Este registro não processa pagamentos.</p>${!s?`<label>Iniciar após a recarga<select name="stationId"><option value="">Guardar no saldo do cliente</option>${state.stations.filter(t=>t.active&&!activeStation(t.id)).map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('')}</select></label>`:''}<button class="primary" ${!m.active?'disabled':''}>Registrar recarga</button></form>`);cashGuard('adicionar tempo');let promotionId=null,mode='minutes';const hour=state.settings.hourCents,field=$('#credit-minutes');/* 3.0.49: pacote gratis (R$ 0,00) troca Forma de pagamento por OBS + chave de autenticacao, ambos obrigatorios */const setFree=on=>{const pay=$('#credit-payment'),free=$('#credit-free'),f=pay.closest('form');pay.classList.toggle('hidden',on);$('#credit-paymix').classList.toggle('hidden',on);free.classList.toggle('hidden',!on);f.paymentMethod.required=!on&&!(window.gzCreditMix&&gzCreditMix.active());f.paymentMethod.disabled=on||!!(window.gzCreditMix&&gzCreditMix.active());f.obs.required=on;f.authPassword.required=on;if(on){f.obs.minLength=3}else{f.obs.value='';f.authPassword.value=''}};
 const minutesFor=c=>hour>0?Math.round(c*60/hour):0,fmtMin=n=>n>=60?`${n} minutos (${duration(n*60).slice(0,5).replace(':','h')}min)`:`${n} minutos`;
 const update=()=>{setFree(!promotionId&&mode==='minutes'&&hour===0);if(promotionId)return;const v=Number(String(field.value).replace(',','.'))||0;if(mode==='minutes')$('#quote').textContent=money(Math.round(v*hour/60));else{const n=minutesFor(Math.round(v*100));$('#quote').textContent=n>0?fmtMin(n):'Valor insuficiente';}};
 const setMode=m=>{mode=m;promotionId=null;document.querySelectorAll('[data-promo]').forEach(b=>b.classList.remove('selected'));if(m==='value'){$('#credit-input-title').textContent='Valor da recarga (R$)';$('#quote-title').textContent='Minutos da recarga';field.min='0.01';field.max='1000000';field.step='0.01';field.value=(hour/100).toFixed(2);}else{$('#credit-input-title').textContent='Quantidade de minutos';$('#quote-title').textContent='Valor da recarga';field.min='1';field.max='43200';field.step='1';field.value='60';}update();};
 document.querySelectorAll('input[name="creditMode"]').forEach(r=>r.onchange=()=>setMode(r.value));
 field.oninput=()=>{promotionId=null;document.querySelectorAll('[data-promo]').forEach(b=>b.classList.remove('selected'));update()};
 document.querySelectorAll('[data-promo]').forEach(b=>b.onclick=()=>{if(mode!=='minutes'){document.querySelector('input[name="creditMode"][value="minutes"]').checked=true;setMode('minutes');}promotionId=b.dataset.promo;const p=state.promotions.find(p=>p.id===promotionId);field.value=p.minutes;$('#quote').textContent=money(p.cents);setFree(p.cents===0);document.querySelectorAll('[data-promo]').forEach(btn=>btn.classList.toggle('selected',btn===b))});
 {const f=$('#modal-body form'),num=()=>Number(String(field.value).replace(',','.'))||0;window.gzCreditMix=payMix($('#credit-paymix'),()=>promotionId?(state.promotions.find(p=>p.id===promotionId)?.cents||0):mode==='minutes'?Math.round(num()*hour/60):Math.round(num()*100),on=>{f.paymentMethod.disabled=on;f.paymentMethod.required=!on;$('#credit-payment').classList.toggle('hidden',on)});f.addEventListener('input',()=>gzCreditMix.paint());f.addEventListener('click',()=>setTimeout(()=>gzCreditMix.paint(),0));}
 formAction(d=>{const v=Number(String(field.value).replace(',','.'))||0;const isFree=!$('#credit-free').classList.contains('hidden');const body={memberId:id,promotionId,paymentMethod:isFree?undefined:d.paymentMethod,stationId:d.stationId||undefined};if(!isFree&&gzCreditMix.active()){body.payments=gzCreditMix.payments();delete body.paymentMethod;}if(isFree){body.obs=String(d.obs||'').trim();body.authPassword=d.authPassword||'';if(body.obs.length<3)throw Error('Informe a OBS do pacote grátis.');if(!body.authPassword)throw Error('Informe a chave de autenticação (sua senha do servidor).');}if(mode==='value'&&!promotionId){body.mode='value';body.cents=Math.round(v*100);if(minutesFor(body.cents)<1)throw Error('Valor insuficiente para 1 minuto.');}else body.minutes=Math.round(v);return api('/credit',body)})}
function editStation(id){const s=state.stations.find(s=>s.id===id)||{};modal(id?'Configurar estação':'Nova estação',`<form><label>Nome<input name="name" required value="${esc(s.name)}"></label><div class="row"><label>Tipo<select name="kind"><option value="tv">Console</option><option value="computer" ${s.kind==='computer'?'selected':''}>Computador / Cliente GameZoney</option></select></label><label>HDMI<select name="hdmi">${[1,2,3,4].map(n=>`<option ${s.hdmi===n?'selected':''}>${n}</option>`).join('')}</select></label></div><label>Sistema da TV<select name="tvType"><option value="vidaa">VIDAA (Hisense/Toshiba) — pareia com PIN</option><option value="android" ${s.tvType==='android'?'selected':''}>Android TV / Google TV — pareia por ADB na rede</option></select></label><label>Endereço IP<input name="ip" placeholder="192.168.1.111" value="${esc(s.ip)}"></label><label>Marca VIDAA (opcional, só VIDAA, detectada automaticamente)<input name="brand" placeholder="tos" value="${esc(s.brand)}" maxlength="16"></label><label><input type="checkbox" name="active" ${s.active!==false?'checked':''}>Estação ativa</label><p class="hint">Computador: depois de salvar, use Associar PC para conectar o cliente instalado na máquina. TV Android: ligue a Depuração ADB pela rede nas Opções do desenvolvedor da TV e use Parear TV.</p><button class="primary">Salvar estação</button></form>`);formAction(d=>api('/stations',{...d,id,active:d.active==='on'}))}
function start(id){const s=state.stations.find(s=>s.id===id);const members=state.members.filter(m=>!m.guest&&m.active&&m.creditSeconds>0&&!activeMember(m.id));
 // 3.0.27: busca unica por nome, nick ou CPF; o resultado e selecionado direto na lista.
 const digits=v=>String(v||'').replace(/\D/g,''),plain=v=>String(v||'').normalize('NFD').replace(/[̀-ͯ]/g,'').toLowerCase();
 modal('Iniciar • '+s.name,`<form><label>Cliente<input id="start-member-search" placeholder="Buscar por nome, nick ou CPF" autocomplete="off"></label><input type="hidden" name="memberId" id="start-member-id"><div id="start-member-list" class="member-pick" role="listbox"></div><p class="hint">${s.kind==='tv'?'A TV será enviada para HDMI '+s.hdmi+'. O tempo inicia após o envio do comando.':'O cronômetro será iniciado e o cliente associado liberará a estação ao sincronizar.'}</p><button class="primary" id="start-confirm" disabled>Iniciar atendimento</button></form>`);
 let chosen='';const list=$('#start-member-list'),input=$('#start-member-search');
 const draw=()=>{const q=plain(input.value.trim()),d=digits(input.value);const found=members.filter(m=>!q||plain(m.name).includes(q)||plain(m.username).includes(q)||(d.length>=3&&digits(m.cpf).includes(d)));
  list.innerHTML=!members.length?'<p class="hint">Nenhum cliente com saldo disponível. Adicione tempo ao cliente primeiro.</p>':found.slice(0,30).map(m=>`<button type="button" class="member-opt${m.id===chosen?' selected':''}" data-member="${esc(m.id)}" role="option"><span><strong>${esc(m.name)}</strong><small>${m.username?'@'+esc(m.username):'Nick não definido'}${m.cpf?' · CPF '+esc(cpfText(m.cpf)):''}</small></span><em>${duration(m.creditSeconds)}</em></button>`).join('')+(found.length>30?`<p class="hint">Mostrando 30 de ${found.length}. Continue digitando para refinar.</p>`:'')||'<p class="hint">Nenhum cliente encontrado com saldo.</p>';
  list.querySelectorAll('[data-member]').forEach(b=>b.onclick=()=>{chosen=b.dataset.member;$('#start-member-id').value=chosen;$('#start-confirm').disabled=false;const m=members.find(x=>x.id===chosen);$('#start-confirm').textContent='Iniciar atendimento • '+m.name;draw();});};
 input.oninput=draw;
 input.onkeydown=e=>{if(e.key!=='Enter')return;e.preventDefault();const first=list.querySelector('[data-member]');if(first&&list.querySelectorAll('[data-member]').length===1)first.click();};
 draw();input.focus();formAction(d=>{if(!d.memberId)throw Error('Selecione o cliente na lista.');return api('/start',{stationId:id,memberId:d.memberId})})}
function finish(id){const s=activeStation(id);modal('Encerrar sessão',`<form><p>Encerrar o atendimento de <strong>${esc(memberNick(s))}</strong>?</p><p class="hint">O saldo restante será devolvido ao cliente. Nas TVs, será solicitado o resumo de sessão finalizada.</p><button class="danger">Confirmar encerramento</button></form>`);formAction(()=>api('/finish',{stationId:id}))}
function promotion(id){const p=state.promotions.find(p=>p.id===id)||{};modal(id?'Editar promoção':'Nova promoção',`<form><label>Nome da promoção<input name="name" maxlength="80" required value="${esc(p.name)}" placeholder="Ex.: Combo 2 horas"></label><div class="row"><label>Minutos<input name="minutes" type="number" required min="1" max="43200" value="${p.minutes||120}"></label><label>Preço total (R$)<input name="price" type="number" required min="0" step="0.01" value="${((p.cents??1400)/100).toFixed(2)}"></label></div><label><input name="active" type="checkbox" ${p.active!==false?'checked':''}>Disponível na recarga</label><button class="primary">Salvar promoção</button></form>`);formAction(async d=>{await api('/promotions',{id,...d,minutes:Number(d.minutes),cents:Math.round(Number(d.price)*100),active:d.active==='on'});if(view==='loyalty')setTimeout(()=>promotionsModal().catch(e=>toast(e.message)),300)})}

function summary(id){const s=state.sessions.find(s=>s.id===id)||historySessions.find(s=>s.id===id);modal('Sessão finalizada',`<h3>${esc(memberNick(s))}</h3><p class="muted">${esc(s.stationName)}</p><div class="summary-list"><div><small>Hora de início</small>${datetime(s.startedAt)}</div><div><small>Hora de término</small>${datetime(s.finishedAt)}</div><div><small>Tempo utilizado</small>${duration(s.usedSeconds)}</div><div><small>Tempo restante devolvido</small>${duration(s.remainingSeconds)}</div></div><p class="hint">${esc(s.reason)}</p>${state.stations.find(t=>t.id===s.stationId)?.kind==='tv'?`<button id="resend" class="primary">Mostrar este resumo na TV</button>`:''}`);if($('#resend'))$('#resend').onclick=async()=>{try{await api('/report',{sessionId:id});toast('Abertura solicitada à TV.');$('#modal').close()}catch(e){$('#modal-error').textContent=e.message}}}
$('#password-button').onclick=()=>{modal('Alterar minha senha','<form><label>Senha atual<input type="text" data-secret autocomplete="off" autocapitalize="off" spellcheck="false" data-lpignore="true" data-1p-ignore data-form-type="other" name="current" required></label><label>Nova senha<input type="text" data-secret autocomplete="off" autocapitalize="off" spellcheck="false" data-lpignore="true" data-1p-ignore data-form-type="other" name="password" minlength="4" maxlength="24" required></label><button class="primary">Alterar senha</button></form>');formAction(d=>api('/password',d))};
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;try{if(a==='hour-config'){hourConfig();return;}if(a==='toggle-cash'){cashHidden=!cashHidden;try{localStorage.setItem('gz-caixa-oculto',cashHidden?'1':'0')}catch{}render();return;}if(a==='pc-layout')editPCLayout(id);if(a==='tv-remove'){const s=state.stations.find(s=>s.id===id);modal('Remover console',`<form><p>Remover <strong>${esc(s.name)}</strong> da lista?</p><p>O histórico de sessões e faturas será preservado. Para voltar a usar este console, cadastre-o de novo em Nova estação.</p><button class="danger">Confirmar remoção</button></form>`);formAction(()=>api('/station/remove',{stationId:id}))}if(a==='pc-remove'){const s=state.stations.find(s=>s.id===id);modal('Remover computador',`<form><p>Remover <strong>${esc(s.name)}</strong> da lista?</p><p>O histórico será preservado e a associação antiga deixará de funcionar. Para retornar, reconfigure o cliente e autorize como novo computador no servidor.</p><button class="danger">Confirmar remoção</button></form>`);formAction(()=>api('/pc/remove',{stationId:id}))}if(a==='admin-create'){modal('Cadastrar administrador','<form><p>Esta conta terá acesso administrativo ao servidor e aos PCs. Não é uma conta de cliente.</p><label>Usuário<input name="username" required maxlength="40" autocomplete="off"></label><label>Senha<input name="password" type="text" data-secret autocomplete="off" autocapitalize="off" spellcheck="false" data-lpignore="true" data-1p-ignore data-form-type="other" required minlength="4" maxlength="24"></label><button class="primary">Criar administrador</button></form>');formAction(d=>api('/operators',{...d,role:'admin'}))}if(a==='pc-approve'){const p=state.pendingPCs.find(p=>p.device===id);modal('Autorizar computador',`<form><p>Confira se o PC <strong>${esc(p.name)}</strong> mostra este código: <strong>${esc(p.code)}</strong>.</p><label>Adicionar como<select name="stationId"><option value="">Novo computador</option>${state.stations.filter(s=>s.kind==='computer'&&s.active&&!s.pcPaired&&!activeStation(s.id)).map(s=>`<option value="${esc(s.id)}">${esc(s.name)}</option>`).join('')}</select></label><label>Nome do novo computador<input name="name" required maxlength="60" value="${esc(p.name)}"></label><button class="primary">Conferi o código · Autorizar</button></form>`);$('#modal-body form').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{const d=Object.fromEntries(new FormData(e.target));const r=await api('/pc/approve',{...d,device:id});modal('Computador autorizado',`<p>${esc(r.stationName)} autorizado. No PC, confirme que a identidade do servidor é:</p><h2>${esc(r.verification)}</h2><p>Depois crie a senha de manutenção para concluir.</p>`);await refresh(true)}catch(e){$('#modal-error').textContent=e.message}finally{e.submitter.disabled=false}};}if(a==='pc-reject'){await api('/pc/reject',{device:id});await refresh(true)}if(a==='pc-enroll'){modal('Associar computador','<form><p>Será criado um arquivo de associação exclusivo para este PC. Uma associação anterior será substituída.</p><p>Copie o arquivo para o computador e selecione-o ao abrir o GameZoney Cliente. Guarde-o somente com a recepção.</p><button class="primary">Gerar arquivo de associação</button></form>');formAction(async()=>{const data=await api('/pc/enroll',{stationId:id});const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download='gamezoney-pc-'+id+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)});}if(a==='recovery-refund'){if(!await ask('Devolver ao cliente o saldo apontado nesta auditoria? Esta ação só pode ser feita uma vez.'))return;const r=await api('/recovery-refund',{id});toast('Saldo devolvido: '+duration(r.seconds));await refresh(true);if(view==='logs')await renderLogs();}if(a==='member-edit')editMember(id);if(a==='credit')credit(id);if(a==='station-edit')editStation(id);if(a==='start')start(id);if(a==='finish')finish(id);if(a==='promotion')promotion(id);if(a==='summary')summary(id);if(a==='pair'){b.disabled=true;await api('/pair',{stationId:id});toast(state.stations.find(s=>s.id===id)?.tvType==='android'?'Na TV: aceite "Permitir depuração?" e marque "Sempre permitir".':'Confira o PIN na tela da TV; use Informar PIN.')}if(a==='pin'){modal('Confirmar PIN da TV','<form><label>PIN exibido agora<input name="pin" inputmode="numeric" pattern="[0-9]{4}" maxlength="4" required autocomplete="off"></label><button class="primary">Confirmar pareamento</button></form>');formAction(d=>api('/pin',{stationId:id,pin:d.pin}))}if(a==='hdmi'){b.disabled=true;await api('/hdmi',{stationId:id});toast('Troca de entrada enviada.')}if(a==='import'){modal('Importar pareamento anterior','<form><p class="hint">Selecione o arquivo tv-1.json ou equivalente da pasta dados da versão anterior. O token fica salvo apenas neste servidor.</p><input type="file" id="pair-file" accept=".json" required><div class="dialog-actions"><button class="primary">Importar</button></div></form>');formAction(async()=>{const file=$('#pair-file').files[0];if(file.size>65536)throw Error('Arquivo muito grande.');await api('/pairing/import',{stationId:id,data:JSON.parse(await file.text())})})}if(a==='operator'){modal('Cadastrar operador','<form><label>Nome de usuário<input name="username" required maxlength="40"></label><label>Senha<input type="text" data-secret autocomplete="off" autocapitalize="off" spellcheck="false" data-lpignore="true" data-1p-ignore data-form-type="other" name="password" minlength="4" maxlength="24" required></label><label>Permissão<select name="role"><option value="operator">Operador de atendimento</option><option value="admin">Administrador</option></select></label><button class="primary">Cadastrar</button></form>');formAction(d=>api('/operators',d))}}catch(error){toast(error.message)}finally{b.disabled=false}});
document.addEventListener('click',e=>{const jump=e.target.closest('[data-view-jump]');if(!jump)return;const target=jump.dataset.viewJump,button=document.querySelector(`nav button[data-view="${target}"]`);if(button)button.click();else if(target==='logs'&&typeof openSessionTab==='function')openSessionTab('logs');});
setInterval(()=>{const now=Date.now()+offset;$('#clock').textContent=new Date(now).toLocaleString('pt-BR',{timeZone:state?.settings.timeZone||'America/Manaus'});document.querySelectorAll('[data-end]').forEach(el=>el.textContent=duration(Math.max(0,Math.ceil((Number(el.dataset.end)-now)/1000))))},1000);
setInterval(()=>{if(state)refresh()},3000);auth().catch(e=>{$('#auth').classList.remove('hidden');$('#auth-error').textContent=e.message});

function pendingPCs(){if(!isAdmin())return '';return (state.pendingPCs||[]).map(p=>`<div class="panel"><h3>PC aguardando autorização: ${esc(p.name)}</h3><p>Endereço: ${esc(p.ip)} · Código no PC: <strong>${esc(p.code)}</strong></p><button class="primary" data-action="pc-approve" data-id="${esc(p.device)}">Autorizar computador</button> <button data-action="pc-reject" data-id="${esc(p.device)}">Recusar</button></div>`).join('')}

function renderMachineSettings(target){const node=target||$('#view');if(!isAdmin()){node.innerHTML='<div class="empty">Somente o administrador pode configurar as máquinas.</div>';return}const p=state.settings.machinePolicy||{taskManager:true,controlPanel:true,securityOptions:true,dateTime:true,revision:1};node.innerHTML=`<div class="panel"><h2>Configuração das máquinas — restrições dos computadores</h2><p>Os PCs precisam do ${gzClient()} (ou mais novo) para aplicar todas as opções atuais. Não afetam as TVs. O acesso administrativo suspende as restrições enquanto o administrador está conectado.</p><p class="hint">No PC, abra Manutenção e entre com uma conta de <strong>Administrador</strong> cadastrada em Contas de acesso. Contas de cliente e de operador de atendimento não liberam restrições.</p><form id="machine-settings"><label><input type="checkbox" name="taskManager" ${p.taskManager?'checked':''}> Bloquear Gerenciador de Tarefas</label><label><input type="checkbox" name="controlPanel" ${p.controlPanel?'checked':''}> Bloquear Painel de Controle e Configurações</label><label><input type="checkbox" name="securityOptions" ${p.securityOptions?'checked':''}> Restringir opções da tela Ctrl+Alt+Del</label><label><input type="checkbox" name="dateTime" ${p.dateTime!==false?'checked':''}> Bloquear configuração de data e hora</label><p class="hint">Bloquear data e hora (${gzClient()} ou superior) fecha o ajuste de data/hora do Windows e o app Configurações durante a sessão, pois a página Data e hora fica dentro dele. O tempo da sessão nunca depende do relógio do Windows.</p><p class="hint">A opção da tela Ctrl+Alt+Del remove Bloquear, Sair e Alterar senha dessa tela. O Gerenciador de Tarefas é controlado pela primeira opção. A combinação Ctrl+Alt+Del continua abrindo a tela protegida do Windows; troca de usuário, energia e outras opções do sistema podem permanecer disponíveis.</p><p class="hint">Na tela de login, o cliente restringe atalhos comuns como Windows, Alt+Tab e Alt+F4. Digitação, Tab, Enter e edição dos campos continuam disponíveis. A manutenção da recepção permanece protegida por senha.</p><p class="hint">As opções marcadas também valem durante o jogo. Desmarcar restaura o estado anterior à instalação, inclusive restrições que já existiam. PCs desconectados mantêm a última configuração recebida.</p><button class="primary">Salvar para todos os PCs</button><span id="machine-saved" role="status"></span></form></div><div class="panel"><h2>Recebimento pelos clientes</h2><p class="hint">Retorno informado pelo aplicativo. Reabra esta aba para atualizar. Revisão atual: ${p.revision}</p>${state.stations.filter(s=>s.kind==='computer').map(s=>{const r=state.pcPolicyReports?.[s.id];return `<p><strong>${esc(s.name)}</strong> — ${state.pcAdminStations?.includes(s.id)?'Acesso administrativo autorizado; restrições suspensas.':!r?'Sem confirmação. Atualize e conecte o cliente.':r.error?'Falha: '+esc(r.error):state.clientVersion&&r.version&&r.version!==state.clientVersion?'Este PC está com o cliente versão '+esc(r.version)+'. Atualize para o '+gzClient()+'.':r.revision===p.revision?'Cliente confirmou aplicação (v'+esc(r.version)+').':'Aguardando aplicação da revisão atual.'}${r&&Date.now()-r.at>15000?' · Sem contato recente.':''}</p>`}).join('')||'<p>Nenhum computador cadastrado.</p>'}</div>`;$('#machine-settings').onsubmit=async e=>{e.preventDefault();const form=e.target,button=form.querySelector('button');button.disabled=true;try{await api('/machine-settings',Object.fromEntries(['taskManager','controlPanel','securityOptions','dateTime'].map(k=>[k,form.elements[k].checked])));await refresh();renderMachineSettings(node);$('#machine-saved').textContent=' Salvo. PCs conectados recebem na próxima consulta.'}catch(err){toast(err.message)}finally{button.disabled=false}}}

function editPCLayout(id){const station=state.stations.find(s=>s.id===id);modal('Layout do login • '+station.name,`<form><p>Selecione um fundo JPG ou PNG para este computador. Requer o ${gzClient()}.</p><label>Imagem de fundo<input id="wallpaper-file" type="file" accept="image/jpeg,image/png"></label><img id="wallpaper-preview" alt="Prévia da imagem selecionada" style="display:none;width:100%;max-height:220px;object-fit:contain"><label>Posição dos campos de login<select name="position"><option value="left">Esquerda</option><option value="center">Centro</option><option value="right">Direita</option></select></label><label><input type="checkbox" name="clear"> Remover imagem e usar fundo escuro</label><p class="hint">O fundo mantém a proporção. O formulário fica sobre um painel escuro para facilitar a leitura. A alteração será recebida quando o cliente estiver conectado.</p><button class="primary">Enviar layout para esta máquina</button></form>`);$('#modal-body select').value=station.loginLayout?.position||'center';let image='';$('#wallpaper-file').onchange=async e=>{image='';try{const f=e.target.files[0];if(!f)return;if(!['image/jpeg','image/png'].includes(f.type)||f.size>15000000)throw Error('Selecione JPG ou PNG de até 15 MB.');const url=URL.createObjectURL(f);try{const img=new Image();img.src=url;await img.decode();const scale=Math.min(1,1920/img.width,1080/img.height),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));const context=canvas.getContext('2d');context.fillStyle='#101115';context.fillRect(0,0,canvas.width,canvas.height);context.drawImage(img,0,0,canvas.width,canvas.height);const data=canvas.toDataURL('image/jpeg',0.88);image=data.split(',')[1];$('#wallpaper-preview').src=data;$('#wallpaper-preview').style.display='block';$('#modal-error').textContent='';}finally{URL.revokeObjectURL(url)}}catch(err){$('#modal-error').textContent=err.message}};formAction(d=>{if(!image&&d.clear!=='on')throw Error('Selecione uma imagem ou marque remover imagem.');return api('/pc/layout',{stationId:id,position:d.position,image,clear:d.clear==='on'})})}

// 3.0.20: importacao de clientes por planilha (Nome, Usuario/Nick, Tempo). As senhas sao criadas pelo
// proprio cliente no primeiro acesso ao PC, igual ao cadastro sem senha.
function importMembersDialog(){
 const model='data:text/csv;charset=utf-8,'+encodeURIComponent('\uFEFFNome;Nick;Tempo;Medalhas de fidelidade\nJoão da Silva;joao.silva;01:30;150\nMaria Souza;maria_s;90;0\n');
 modal('Importar clientes',`<form id="import-form"><p class="hint">Planilha do Excel (.xlsx) ou CSV com as colunas <strong>Nome</strong>, <strong>Nick</strong>, <strong>Tempo</strong> e <strong>Medalhas de fidelidade</strong>. O tempo pode ser 01:30 (horas:minutos), 90 (minutos) ou 1h30. As medalhas podem ser 150 ou 12,5 (vazio = 0) e entram como saldo inicial no extrato de medalhas. Cada cliente entra sem senha e cria a senha no primeiro acesso ao PC. Todos participam automaticamente do programa de fidelidade. Nicks já cadastrados não são alterados.</p><p><a href="${model}" download="modelo-importacao-clientes.csv">Baixar modelo</a></p><label>Arquivo<input type="file" id="import-file" accept=".xlsx,.csv,.txt" required></label><div id="import-preview"></div><button class="primary" id="import-confirm" disabled>Importar clientes</button></form>`);
 let rows=[];
 $('#import-file').onchange=async e=>{const file=e.target.files[0];rows=[];$('#import-confirm').disabled=true;$('#import-preview').innerHTML='<p class="hint">Lendo a planilha…</p>';if(!file)return;try{const data=await new Promise((ok,err)=>{const r=new FileReader();r.onload=()=>ok(String(r.result).split(',')[1]||'');r.onerror=()=>err(Error('Não foi possível ler o arquivo.'));r.readAsDataURL(file)});const p=await api('/members/import/preview',{fileName:file.name,data});rows=p.rows;const n=rows.filter(r=>r.status==='new'),x=rows.filter(r=>r.status==='exists'),bad=rows.filter(r=>r.status==='error');const total=n.reduce((a,r)=>a+r.seconds,0),points=n.reduce((a,r)=>a+(r.pointsMilli||0),0);
  $('#import-preview').innerHTML=`<div class="balance"><span>Novos clientes</span><strong>${n.length}</strong></div><div class="balance"><span>Saldo inicial total</span><strong>${duration(total)}</strong></div><div class="balance"><span>Medalhas de fidelidade total</span><strong>${loyaltyPointsText(points)}</strong></div><p class="hint">${x.length} já cadastrado(s) serão ignorados · ${bad.length} linha(s) com erro.</p><div class="table-wrap" style="max-height:260px;overflow:auto"><table><thead><tr><th>Linha</th><th>Nome</th><th>Nick</th><th>Tempo</th><th>Medalhas</th><th>Situação</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r.line}</td><td>${esc(r.name)}</td><td>${esc(r.username)}</td><td>${r.status==='error'?esc(r.timeText):duration(r.seconds)}</td><td>${r.pointsMilli==null?esc(r.pointsText):loyaltyPointsText(r.pointsMilli)}</td><td>${r.status==='new'?'<span class="badge on">NOVO</span>':r.status==='exists'?esc(r.note):'<span class="badge red">ERRO</span> '+esc(r.error)}</td></tr>`).join('')}</tbody></table></div>`;
  $('#import-confirm').disabled=!n.length;$('#import-confirm').textContent=n.length?`Importar ${n.length} cliente(s)`:'Nenhum cliente novo para importar';}catch(err){$('#import-preview').innerHTML='<p class="error">'+esc(err.message)+'</p>'}};
 $('#import-form').onsubmit=async e=>{e.preventDefault();const button=$('#import-confirm');button.disabled=true;try{const r=await api('/members/import',{rows:rows.filter(r=>r.status==='new')});$('#modal').close();await refresh(true);toast(`${r.imported} cliente(s) importado(s) com ${duration(r.seconds)} de saldo inicial e ${loyaltyPointsText(r.pointsMilli||0)} medalha(s) de fidelidade.`)}catch(err){$('#modal-error').textContent=err.message;button.disabled=false}};
}
document.addEventListener('click',e=>{if(e.target.closest('[data-action="member-import"]'))importMembersDialog();});

// 3.0.21: liberar a estacao para VISITANTE (sem cadastro). Informe apenas o tempo (ou promocao) e a forma
// de pagamento: a sessao inicia na hora com o nome "Visitante". Visitante nao acumula medalhas e o tempo
// nao utilizado nao fica guardado.
function guestStart(id){const t=state.stations.find(s=>s.id===id);if(!t)return;
 // 3.0.32: visitante tambem escolhe "Em minutos" ou "Em valor", igual ao Adicionar tempo.
 modal('Visitante • '+t.name,`<form><p class="hint">Liberação imediata sem cadastro. A estação inicia com o nome <strong>Visitante</strong>. O tempo não utilizado não fica guardado e o visitante não acumula medalhas de fidelidade.</p><span class="eyebrow">ESCOLHA UMA PROMOÇÃO</span><div class="promo-options">${state.promotions.filter(p=>p.active).map(p=>`<button type="button" data-guest-promo="${p.id}"><strong>${esc(p.name)}</strong><small>${p.minutes} min · ${money(p.cents)}</small></button>`).join('')||'<p class="hint">Nenhuma promoção ativa.</p>'}</div>${rechargeModeHtml('guestMode')}<label><span id="guest-input-title">Quantidade de minutos</span><input id="guest-minutes" name="amount" type="number" min="1" max="43200" step="1" value="60" required></label><div class="balance locked"><span id="guest-quote-title">Valor</span><strong class="price" id="guest-quote">${money(state.settings.hourCents)}</strong></div><label>Forma de pagamento<select name="paymentMethod" required><option value="">Selecione</option><option value="cash">Dinheiro</option><option value="pix">Pix</option><option value="credit">Cartão (Crédito)</option><option value="debit">Cartão (Débito)</option></select></label><div id="guest-paymix">${payMixHtml(PAY_RECHARGE)}</div><button class="primary">Liberar ${esc(t.name)} agora</button></form>`);cashGuard('liberar visitantes');
 const r=rechargeMode({radio:'guestMode',field:'#guest-minutes',title:'#guest-input-title',quoteTitle:'#guest-quote-title',quote:'#guest-quote',promo:'data-guest-promo',quoteLabel:'Valor'});
 {const f=$('#modal-body form'),sel=f.paymentMethod;var gmix=payMix($('#guest-paymix'),()=>r.cents(),on=>{sel.disabled=on;sel.required=!on;sel.closest('label').classList.toggle('hidden',on)});f.addEventListener('input',()=>gmix.paint());f.addEventListener('click',()=>setTimeout(()=>gmix.paint(),0));}
 formAction(d=>{const mix=gmix.payments();return api('/guest-start',{stationId:id,...(mix?{payments:mix}:{paymentMethod:d.paymentMethod}),...r.body()})});}
// Seletor "Em minutos / Em valor" reaproveitado pelos dialogos de visitante.
function rechargeModeHtml(name){return `<div class="credit-mode" role="radiogroup" aria-label="Informar recarga"><span>Informar recarga</span><label><input type="radio" name="${name}" value="minutes" checked> Em minutos</label><label><input type="radio" name="${name}" value="value"> Em valor</label></div>`;}
function rechargeMode(o){let promotionId=null,mode='minutes';const hour=state.settings.hourCents,field=$(o.field),promos=()=>document.querySelectorAll('['+o.promo+']');
 const minutesFor=c=>hour>0?Math.round(c*60/hour):0,amount=()=>Number(String(field.value).replace(',','.'))||0,fmtMin=n=>n>=60?`${n} minutos (${duration(n*60).slice(0,5).replace(':','h')}min)`:`${n} minutos`;
 const cents=()=>{if(promotionId){const p=state.promotions.find(p=>p.id===promotionId);return p?p.cents:0}return mode==='value'?Math.round(amount()*100):Math.round(amount()*hour/60)};
 const minutes=()=>{if(promotionId){const p=state.promotions.find(p=>p.id===promotionId);return p?p.minutes:0}return mode==='value'?minutesFor(Math.round(amount()*100)):Math.round(amount())};
 const update=()=>{if(o.quote){if(promotionId)$(o.quote).textContent=money(cents());else if(mode==='minutes')$(o.quote).textContent=money(cents());else{const n=minutes();$(o.quote).textContent=n>0?fmtMin(n):'Valor insuficiente';}}o.onChange&&o.onChange()};
 const clear=()=>{promotionId=null;promos().forEach(b=>b.classList.remove('selected'))};
 const setMode=m=>{mode=m;clear();if(m==='value'){$(o.title).textContent=o.valueTitle||'Valor da recarga (R$)';if(o.quoteTitle)$(o.quoteTitle).textContent='Minutos';field.min='0.01';field.max='1000000';field.step='0.01';field.value=(hour/100).toFixed(2);}else{$(o.title).textContent=o.minutesTitle||'Quantidade de minutos';if(o.quoteTitle)$(o.quoteTitle).textContent=o.quoteLabel||'Valor';field.min='1';field.max='43200';field.step='1';field.value='60';}update()};
 document.querySelectorAll(`input[name="${o.radio}"]`).forEach(x=>x.onchange=()=>setMode(x.value));
 field.oninput=()=>{clear();update()};
 promos().forEach(b=>b.onclick=()=>{if(mode!=='minutes'){document.querySelector(`input[name="${o.radio}"][value="minutes"]`).checked=true;setMode('minutes');}promotionId=b.getAttribute(o.promo);const p=state.promotions.find(p=>p.id===promotionId);field.value=p.minutes;promos().forEach(x=>x.classList.toggle('selected',x===b));update()});
 update();
 return{cents,minutes,mode:()=>mode,body(){if(promotionId)return{promotionId};if(mode==='value'){const c=Math.round(amount()*100);if(minutesFor(c)<1)throw Error('Valor insuficiente para 1 minuto.');return{mode:'value',cents:c}}return{minutes:Math.round(amount())}}};}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action="guest-start"]');if(b&&!b.disabled)guestStart(b.dataset.id);});

// 3.0.22: varios visitantes de uma vez (grupo). Limite = estacoes livres no momento.
function freeStations(){return state.stations.filter(t=>t.active&&!activeStation(t.id)&&!state.pcAdminStations?.includes(t.id)&&(t.kind!=='computer'||(t.pcPaired&&state.status[t.id]?.connected)));}
function guestBatch(){const free=freeStations();
 if(!free.length){modal('Visitantes em grupo','<p class="hint">Nenhuma estação livre e conectada no momento.</p>');return}
 modal('Visitantes em grupo',`<form id="guest-batch-form"><p class="hint">Libera várias estações livres de uma vez com o nome <strong>Visitante</strong>. Cada estação recebe o mesmo tempo e gera sua própria venda. Máximo agora: <strong>${free.length}</strong> estação(ões) livre(s).</p><label>Quantidade de visitantes<input id="gb-qty" type="number" min="1" max="${free.length}" value="${free.length}"></label><div class="gb-list" style="max-height:220px;overflow:auto;display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:6px;margin:6px 0 12px">${free.map(t=>`<label style="display:flex;gap:8px;align-items:center;margin:0"><input type="checkbox" class="gb-st" value="${t.id}" checked>${esc(t.name)}</label>`).join('')}</div><span class="eyebrow">ESCOLHA UMA PROMOÇÃO</span><div class="promo-options">${state.promotions.filter(p=>p.active).map(p=>`<button type="button" data-gb-promo="${p.id}"><strong>${esc(p.name)}</strong><small>${p.minutes} min · ${money(p.cents)}</small></button>`).join('')||'<p class="hint">Nenhuma promoção ativa.</p>'}</div>${rechargeModeHtml('gbMode')}<label><span id="gb-input-title">Minutos por visitante</span><input id="gb-minutes" type="number" min="1" max="43200" step="1" value="60" required></label><div class="balance"><span>Valor por visitante</span><strong id="gb-each">${money(state.settings.hourCents)}</strong></div><div class="balance"><span>Total</span><strong class="price" id="gb-total"></strong></div><label>Forma de pagamento<select id="gb-pay" required><option value="">Selecione</option><option value="cash">Dinheiro</option><option value="pix">Pix</option><option value="credit">Cartão (Crédito)</option><option value="debit">Cartão (Débito)</option></select></label><button class="primary" id="gb-go">Liberar</button><div id="gb-result"></div></form>`);cashGuard('liberar visitantes');
 const boxes=()=>[...document.querySelectorAll('.gb-st')];let rm;
 const update=()=>{if(!rm)return;const n=boxes().filter(b=>b.checked).length,c=rm.cents(),mins=rm.minutes();$('#gb-each').textContent=money(c)+(mins>0?' • '+mins+' min':' • valor insuficiente');$('#gb-total').textContent=money(c*n);$('#gb-go').textContent=n?`Liberar ${n} visitante(s) agora`:'Selecione as estações';$('#gb-go').disabled=!n;};
 rm=rechargeMode({radio:'gbMode',field:'#gb-minutes',title:'#gb-input-title',promo:'data-gb-promo',minutesTitle:'Minutos por visitante',valueTitle:'Valor por visitante (R$)',onChange:()=>update()});
 $('#gb-qty').oninput=e=>{const n=Math.max(0,Math.min(free.length,Number(e.target.value)||0));boxes().forEach((b,i)=>b.checked=i<n);update()};
 boxes().forEach(b=>b.onchange=()=>{$('#gb-qty').value=boxes().filter(x=>x.checked).length;update()});
 update();
 $('#guest-batch-form').onsubmit=async e=>{e.preventDefault();const ids=boxes().filter(b=>b.checked).map(b=>b.value);const pay=$('#gb-pay').value;$('#modal-error').textContent='';if(!pay){$('#modal-error').textContent='Selecione a forma de pagamento.';return}const go=$('#gb-go');go.disabled=true;go.textContent='Liberando…';
  try{const r=await api('/guest-start-batch',{stationIds:ids,...rm.body(),paymentMethod:pay});$('#gb-result').innerHTML=`<div class="balance"><span>Liberados</span><strong>${r.success} de ${r.total}</strong></div><div class="balance"><span>Total registrado</span><strong>${money(r.cents)}</strong></div><ul>${r.results.map(x=>`<li>${esc(x.name)}: ${x.ok?'liberado':'<span class="error">'+esc(x.message)+'</span>'}</li>`).join('')}</ul>`;go.textContent='Concluído';await refresh(true);toast(`${r.success} visitante(s) liberado(s).`)}catch(err){$('#modal-error').textContent=err.message;go.disabled=false;update()}};
}
document.addEventListener('click',e=>{if(e.target.closest('[data-action="guest-batch"]'))guestBatch();});

// 3.0.24: Configuração = Hora e configurações + Configuração das máquinas + Contas de acesso.
// Contas de administrador e operador juntas. Somente o administrador principal (primeiro administrador
// do servidor) ativa/desativa contas; a conta principal não pode ser desativada.
async function renderAccounts(){const node=$('#cfg-accounts');if(!node||!isAdmin())return;const d=await api('/operators');if(!$('#cfg-accounts'))return;
 node.innerHTML=`<div class="panel"><div class="toolbar"><div><h2>Contas de acesso</h2><p class="hint">Administradores acessam todo o servidor e também entram nos PCs pelo botão Entrar do cliente (modo administrador). Operadores fazem atendimento (sessões, recargas, clientes e vendas).${d.canManage?'':' Somente o administrador principal pode ativar ou desativar contas.'}</p></div><button class="primary" data-account-new>+ Cadastrar conta</button></div><div class="table-wrap"><table><thead><tr><th>Usuário</th><th>Permissão</th><th>Situação</th><th>Conta ativa</th></tr></thead><tbody>${d.operators.map(o=>`<tr><td>${esc(o.username)}${o.owner?'<small class="subtext">Administrador principal</small>':''}${o.id===state.operator.id?'<small class="subtext">Você</small>':''}</td><td>${o.role==='admin'?'Administrador':'Operador'}</td><td><span class="badge ${o.active?'on':'red'}">${o.active?'ATIVA':'DESATIVADA'}</span></td><td><label class="switch" title="${o.owner?'A conta principal não pode ser desativada':d.canManage?'Ativar/desativar':'Somente o administrador principal'}"><input type="checkbox" data-account-toggle="${o.id}" ${o.active?'checked':''} ${o.owner||!d.canManage?'disabled':''}><span></span></label></td></tr>`).join('')}</tbody></table></div></div>`;
 node.querySelectorAll('[data-account-toggle]').forEach(c=>c.onchange=async()=>{const o=d.operators.find(x=>x.id===c.dataset.accountToggle);if(!c.checked&&!await ask(`Desativar a conta "${o.username}"? Ela será desconectada e não poderá entrar no servidor nem liberar PCs.`)){c.checked=true;return}c.disabled=true;try{await api('/operators/status',{id:o.id,active:c.checked});toast(c.checked?'Conta reativada.':'Conta desativada.');}catch(e){toast(e.message)}renderAccounts().catch(e=>toast(e.message))});
 node.querySelector('[data-account-new]').onclick=()=>{modal('Cadastrar conta','<form><label>Nome de usuário<input name="username" required maxlength="40" autocomplete="off"></label><label>Senha<input type="text" data-secret autocomplete="off" autocapitalize="off" spellcheck="false" data-lpignore="true" data-1p-ignore data-form-type="other" name="password" minlength="4" maxlength="24" required></label><label>Permissão<select name="role"><option value="operator">Operador de atendimento</option><option value="admin">Administrador</option></select></label><p class="hint">Não é uma conta de cliente. Administrador também libera os PCs em Manutenção.</p><button class="primary">Cadastrar</button></form>');formAction(async x=>{await api('/operators',x);setTimeout(()=>renderAccounts().catch(e=>toast(e.message)),150)})};
}

// 3.0.30: remover promocao (Configuracao > Promocoes)
document.addEventListener('click',async e=>{const b=e.target.closest('[data-promo-remove]');if(!b)return;const p=state.promotions.find(x=>x.id===b.dataset.promoRemove);if(!p||!await ask(`Remover a promoção "${p.name}"? Ela deixa de aparecer nas recargas. As faturas já registradas não mudam.`))return;b.disabled=true;try{await api('/promotions/remove',{id:p.id});await refresh(true);toast('Promoção removida.');if($('#modal').open&&$('#modal-title').textContent==='Promoções')await promotionsModal()}catch(err){toast(err.message);b.disabled=false}});

// 3.0.32: com o caixa fechado so o administrador principal registra recargas, visitantes e vendas.
function cashBlocked(){return !!state&&!state.cashOpen&&!state.cashBypass;}
function cashGuard(what){const body=$('#modal-body');if(!body)return;if(cashBlocked()){body.insertAdjacentHTML('afterbegin',`<div class="pdv-cash-warn">Caixa fechado. Abra o caixa para ${what}. <button type="button" data-cash-goto>Abrir caixa</button></div>`);body.querySelectorAll('button.primary').forEach(b=>b.disabled=true);}else if(state&&!state.cashOpen&&state.cashBypass){body.insertAdjacentHTML('afterbegin','<p class="hint cash-bypass">Caixa fechado: como administrador principal você pode registrar mesmo assim, mas este valor não entra em nenhum caixa.</p>');}}

// 3.0.35: organizar as estacoes de Computadores/TVs por nome (A-Z / Z-A). Ordem natural: "PC 2" antes de "PC 10".
// A escolha fica guardada neste computador. Clicar de novo no botao ativo volta para a ordem de cadastro.
function sortedStations(){const list=[...state.stations];if(!stationSort)return list;const cmp=(a,b)=>String(a.name||'').localeCompare(String(b.name||''),'pt-BR',{numeric:true,sensitivity:'base'});list.sort(cmp);if(stationSort==='za')list.reverse();return list;}
document.addEventListener('click',e=>{const b=e.target.closest('[data-station-sort]');if(!b)return;stationSort=stationSort===b.dataset.stationSort?'':b.dataset.stationSort;try{if(stationSort)localStorage.setItem('gz.stationSort',stationSort);else localStorage.removeItem('gz.stationSort');localStorage.removeItem('prime.stationSort')}catch{}render();});
